    ResponseEntity<CancellationResultResponse> reportUnavailability(
        @Parameter(hidden = true) Principal principal,
        // 대상 숙소 식별자. 가정: 필드명 propertyId, 필수 1~64자 opaque 문자열로 정해 저장소 형식을 노출하지 않고 대상을 구분한다.
        @Parameter(description = "대상 숙소 식별자. 가정: 필드명 propertyId, 필수 1~64자 opaque 문자열로 정해 저장소 형식을 노출하지 않고 대상을 구분한다.", required = true, schema = @Schema(type = "string", pattern = "\\S"), example = "prop_1")
        @NotBlank @Size(min = 1, max = 64) String propertyId,
        // 대상 예약 식별자. 가정: 필드명 reservationId, 필수 1~64자 opaque 문자열로 정해 저장소 형식을 노출하지 않고 대상을 구분한다.
        @Parameter(description = "대상 예약 식별자. 가정: 필드명 reservationId, 필수 1~64자 opaque 문자열로 정해 저장소 형식을 노출하지 않고 대상을 구분한다.", required = true, schema = @Schema(type = "string", pattern = "\\S"), example = "rsv_1")
        @NotBlank @Size(min = 1, max = 64) String reservationId,
        // 가정: Idempotency-Key를 필수 1~128자 nonblank 문자열로 받아 파트너 계정·작업·키를 단위로 최초 경로와 본문을 보존한다. 같은 입력은 최초 응답을 재생하고 다른 숙소·예약·사유·확인 값은 409로 거절한다. 네트워크 재전송으로 취소·점유 해제·환불 작업이 중복되는 것을 막기 위한 선택이다.
        @Parameter(description = "가정: Idempotency-Key를 필수 1~128자 nonblank 문자열로 받아 파트너 계정·작업·키를 단위로 최초 경로와 본문을 보존한다. 같은 입력은 최초 응답을 재생하고 다른 숙소·예약·사유·확인 값은 409로 거절한다.", required = true, schema = @Schema(type = "string", pattern = "\\S"), example = "unavailability-20261216-001")
        @NotBlank @Size(min = 1, max = 128) String idempotencyKey,
        @io.swagger.v3.oas.annotations.parameters.RequestBody(required = true, description = "사유와 전체 취소 확인만 입력한다. 비용과 환불액은 서버가 현재 상태 및 최초 취소 결과로 결정한다.", content = @Content(schema = @Schema(implementation = UnavailabilityRequest.class), examples = @ExampleObject(value = "{\"reason\":\"수도 배관 파손으로 예약 객실을 제공할 수 없습니다.\",\"confirmEntireReservation\":true}")))
        @Valid UnavailabilityRequest request);
